using Bool = bool;

inline bool llfsm_parse_Bool(const std::string &text, Bool &out)
{
    if (text == "true" || text == "false") {
        out = text == "true";
        return true;
    }
    return false;
}

using Code = int;

inline bool llfsm_parse_Code(const std::string &text, Code &out)
{
    char *end = nullptr;
    errno = 0;
    long value = std::strtol(text.c_str(), &end, 10);
    if (end == text.c_str() || *end != '\0' || errno != 0 || value < 0 || value > 15) {
        return false;
    }
    out = static_cast<int>(value);
    return true;
}

