void Interlock_Machine::llfsm_ringlet(llfsm_Arrangement &llfsm_arrangement)
{
    Bool &motorOn = llfsm_arrangement.motorOn;
    const Bool doorClosed = llfsm_arrangement.llfsm_environment.doorClosed;
    (void)llfsm_arrangement;
    (void)doorClosed;
    (void)motorOn;
    for (;;) {
        if (llfsm_entered) {
            llfsm_entered = false;
            switch (llfsm_pc) {
            case Interlock_State::Running:
                motorOn = true;
                logEvent(1);
                break;
            case Interlock_State::Halting:
                motorOn = false;
                logEvent(2);
                break;
            default:
                break;
            }
        }
        bool llfsm_fired = true;
        switch (llfsm_pc) {
        case Interlock_State::Idle:
            if (isSafe(doorClosed)) {
                llfsm_pc = Interlock_State::Running;
            } else {
                llfsm_fired = false;
            }
            break;
        case Interlock_State::Running:
            if (!doorClosed) {
                llfsm_pc = Interlock_State::Halting;
            } else {
                llfsm_fired = false;
            }
            break;
        case Interlock_State::Halting:
            if (true) {
                llfsm_pc = Interlock_State::Idle;
            } else {
                llfsm_fired = false;
            }
            break;
        default:
            llfsm_fired = false;
            break;
        }
        if (!llfsm_fired) {
            return;
        }
        llfsm_entered = true;
        if (!llfsm_is_pass_through(llfsm_pc)) {
            return;
        }
    }
}

